import openpyxl
from datetime import datetime, timedelta

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')

# Get the source sheet
source_sheet = wb['Imported Data']

# Get the target sheet
target_sheet = wb['Items Older than 30 days']

# Extract all dates from column E (starting from row 2, row 1 is header)
dates = []
for row in source_sheet.iter_rows(min_row=2, max_col=5, min_col=5):
    cell = row[0]
    if cell.value is not None:
        # Handle both datetime objects and string dates
        if isinstance(cell.value, datetime):
            dates.append(cell.value)
        elif isinstance(cell.value, str):
            try:
                dt = datetime.strptime(cell.value, '%Y-%m-%d %H:%M:%S')
                dates.append(dt)
            except ValueError:
                try:
                    dt = datetime.strptime(cell.value, '%Y-%m-%d')
                    dates.append(dt)
                except ValueError:
                    pass

# Find the maximum date
if dates:
    max_date = max(dates)
else:
    max_date = None

# Calculate the threshold date (30 days older than max date)
if max_date:
    threshold_date = max_date - timedelta(days=30)
else:
    threshold_date = None

# Collect rows where date in column E is more than 30 days older than max date
# "More than 30 days older" means date < threshold_date
rows_to_copy = []

# First, get the header row (row 1)
header_row = []
for col in range(1, 21):  # Columns A to T (20 columns)
    cell = source_sheet.cell(row=1, column=col)
    header_row.append(cell.value)

rows_to_copy.append(header_row)

# Now iterate through data rows
for row_idx in range(2, source_sheet.max_row + 1):
    date_cell = source_sheet.cell(row=row_idx, column=5)
    date_val = date_cell.value

    if date_val is None:
        continue

    # Parse date
    if isinstance(date_val, datetime):
        row_date = date_val
    elif isinstance(date_val, str):
        try:
            row_date = datetime.strptime(date_val, '%Y-%m-%d %H:%M:%S')
        except ValueError:
            try:
                row_date = datetime.strptime(date_val, '%Y-%m-%d')
            except ValueError:
                continue
    else:
        continue

    # Check if date is more than 30 days older than max date
    if threshold_date and row_date < threshold_date:
        row_data = []
        for col in range(1, 21):  # Columns A to T
            cell = source_sheet.cell(row=row_idx, column=col)
            row_data.append(cell.value)
        rows_to_copy.append(row_data)

# Write to target sheet
for row_idx, row_data in enumerate(rows_to_copy, start=1):
    for col_idx, value in enumerate(row_data, start=1):
        target_sheet.cell(row=row_idx, column=col_idx, value=value)

# Delete column Z in sheet 2 (Items Older than 30 days)
# Column Z is column 26
target_sheet.delete_cols(26)

# Save the workbook
wb.save('output.xlsx')
