import openpyxl
from datetime import datetime, timedelta
import calendar

def get_payment_dates(maturity_date, frequency, start_date):
    """
    Generate payment dates working backwards from maturity_date.
    frequency: 1 (annual), 2 (semi-annual), 4 (quarterly)
    start_date: the earliest date in the header row (E4)
    """
    payments = []
    current_date = maturity_date

    # Determine the month offset based on frequency
    if frequency == 1:
        month_offset = 12
    elif frequency == 2:
        month_offset = 6
    elif frequency == 4:
        month_offset = 3
    else:
        return payments

    # Work backwards from maturity
    while current_date >= start_date:
        payments.append(current_date)
        # Subtract month_offset months
        month = current_date.month - month_offset
        year = current_date.year
        while month <= 0:
            month += 12
            year -= 1

        # Handle day overflow (e.g., Jan 31 -> Nov 30)
        day = current_date.day
        max_day = calendar.monthrange(year, month)[1]
        if day > max_day:
            day = max_day

        current_date = current_date.replace(year=year, month=month, day=day)

    return sorted(payments)

def main():
    # Load the workbook
    wb = openpyxl.load_workbook('input.xlsx')
    ws = wb.active

    # Get the date headers from row 4, columns E to AB
    # E is column 5, AB is column 28
    date_headers = []
    for col in range(5, 29):  # E to AB inclusive
        cell_value = ws.cell(row=4, column=col).value
        if isinstance(cell_value, datetime):
            date_headers.append(cell_value)
        elif isinstance(cell_value, str):
            try:
                # Try parsing string date
                dt = datetime.strptime(cell_value.split()[0], '%Y-%m-%d')
                date_headers.append(dt)
            except:
                date_headers.append(None)
        else:
            date_headers.append(None)

    # Find the earliest date in headers for filtering
    valid_dates = [d for d in date_headers if d is not None]
    if valid_dates:
        start_date = min(valid_dates)
    else:
        start_date = datetime(2022, 1, 1)

    # Process rows 6 to 25
    for row in range(6, 26):
        # Get bond data
        principal = ws.cell(row=row, column=1).value
        interest = ws.cell(row=row, column=2).value
        frequency = ws.cell(row=row, column=3).value
        maturity = ws.cell(row=row, column=4).value

        # Skip if any essential data is missing
        if principal is None or interest is None or frequency is None or maturity is None:
            for col in range(5, 29):
                ws.cell(row=row, column=col).value = "-"
            continue

        # Ensure maturity is a datetime
        if isinstance(maturity, str):
            try:
                maturity = datetime.strptime(maturity.split()[0], '%Y-%m-%d')
            except:
                for col in range(5, 29):
                    ws.cell(row=row, column=col).value = "-"
                continue

        # Generate payment dates
        payment_dates = get_payment_dates(maturity, int(frequency), start_date)

        # Fill the cashflow cells
        for col_idx, col in enumerate(range(5, 29)):
            header_date = date_headers[col_idx]

            if header_date is None:
                ws.cell(row=row, column=col).value = "-"
                continue

            # Check if this date is a payment date
            if header_date in payment_dates:
                # Check if it's the maturity date
                if header_date == maturity:
                    # Principal + Interest
                    ws.cell(row=row, column=col).value = principal + interest
                else:
                    # Interest only
                    ws.cell(row=row, column=col).value = interest
            else:
                ws.cell(row=row, column=col).value = "-"

    # Center align the entire E6:AB25 range
    for row in range(6, 26):
        for col in range(5, 29):
            cell = ws.cell(row=row, column=col)
            if cell.alignment is None:
                cell.alignment = openpyxl.styles.Alignment(horizontal='center')
            else:
                cell.alignment = openpyxl.styles.Alignment(
                    horizontal='center',
                    vertical=cell.alignment.vertical,
                    wrapText=cell.alignment.wrapText
                )

    # Save the workbook
    wb.save('output.xlsx')

if __name__ == '__main__':
    main()
